//! Differential command/config/trust/provenance acceptance for ledger C08.
//!
//! `c_cmd-evidence.json` is generated by `tests/c_cmd-reference.mjs`, which imports
//! the UNCHANGED pinned `pi-cursor-sdk@0.5.3` sources (asserting their sha256) and
//! the retained rpi worker port, runs the same scripted scenarios through both and
//! records COMPLETE values. This test compares every recorded reference/candidate
//! pair for equality and pins the C08 claims the ledger asks for:
//!
//! * config precedence, trust levels and safety caps (`cursor-config.ts`),
//! * project-config trust: untrusted projects never load project config,
//! * private (0o600) atomic config writes and merge preservation,
//! * setting-source, environment-boolean and API-key normalization,
//! * stable reconstructed request-provenance digest and occupancy floor,
//! * command/flag/provider registration identity consumed by the native host facade.
use serde_json::Value;

const EVIDENCE: &str = include_str!("c_cmd-evidence.json");

/// sha256 of every upstream file the reference script imports. These are also the
/// hashes pinned in `pi-rust/docs/provider-parity/file-mapping.json`.
const UPSTREAM_HASHES: &[(&str, &str)] = &[
    ("src/cursor-config.ts", "1721a93ae3266d87b78ebf406c46cf71cb4d63b7fc476cded717fd43ec341117"),
    ("src/cursor-setting-sources.ts", "aa14f857e1825cb6589bc4683105b691ee6212dc631034feb7623bb47d53e4a9"),
    ("shared/cursor-setting-sources.mjs", "c2a6a0d78c2308c51176f90d85fa46bd86a8f5719992e99c5a761d04b8f024fe"),
    ("src/cursor-env-boolean.ts", "b7a9b58f5e85f6f1ebea64a0c11afa298542debbacff2a4ae1636624ef6a34ba"),
    ("src/cursor-request-provenance.ts", "c1b230ccde1cf5cc8a71778b4653b1500a103c35076f6b954a8e17d0e5aa6494"),
    ("src/cursor-api-key.ts", "228262af27698d38169b048d4388c34975e2d66265938dc4abbf040e4e0faa67"),
    ("src/index.ts", "42924f74cb383e761a2fd547d5b1c14e7167b125777794f955ea4103118b2607"),
    ("src/cursor-state.ts", "9ed0f11214eb6df5c704963eff5bcca7b321070f7c94289e3e9dc256f33ebc00"),
    ("src/cursor-runtime-state.ts", "b7689529e221039f6084f721e49c990fa7354f00f0bda7c67a7eb8c89b606d62"),
    ("src/cursor-usage-command.ts", "7d7a74fdff69bc9fbb63d124d26adcee2454115361496861d3912d4680dcd98e"),
];

fn evidence() -> Value {
    serde_json::from_str(EVIDENCE).expect("c_cmd-evidence.json is valid JSON")
}

fn cases(evidence: &Value) -> &Vec<Value> {
    evidence["cases"].as_array().expect("cases is an array")
}

fn case<'a>(evidence: &'a Value, group: &str, name: &str) -> &'a Value {
    cases(evidence)
        .iter()
        .find(|entry| entry["group"] == group && entry["name"] == name)
        .unwrap_or_else(|| panic!("missing case {group} / {name}"))
}

fn reference(evidence: &Value, group: &str, name: &str) -> Value {
    case(evidence, group, name)["reference"].clone()
}

#[test]
fn evidence_is_complete_and_generated_from_the_pinned_upstream() {
    let evidence = evidence();
    assert_eq!(evidence["status"], "pass");
    assert_eq!(evidence["schema"], "rpi-cursor-c-cmd-evidence/1");
    assert_eq!(evidence["runtime"]["node"], "24.22.0");
    // The pinned adapter's own dependency graph (not the integrated Pi 1.3.0 harness).
    assert_eq!(evidence["provenance"]["piCodingAgentVersion"], "1.1.0");
    assert_eq!(evidence["provenance"]["piAiVersion"], "1.1.0");
    assert_eq!(evidence["provenance"]["cursorSdkVersion"], "1.0.37");
    assert_eq!(evidence["provenance"]["piCursorSdkVersion"], "0.5.3");
    assert_eq!(evidence["determinism"]["reference"], true);
    assert_eq!(evidence["determinism"]["candidate"], true);
    for (file, hash) in UPSTREAM_HASHES {
        assert_eq!(
            evidence["provenance"]["upstream"][file], *hash,
            "upstream hash for {file}"
        );
    }
    // Every port file is recorded as a 64-character hex digest.
    let port = evidence["provenance"]["port"]
        .as_object()
        .expect("port hashes are an object");
    assert_eq!(port.len(), 10);
    for (file, hash) in port {
        let hash = hash.as_str().expect("port hash is a string");
        assert_eq!(hash.len(), 64, "port hash length for {file}");
        assert!(hash.bytes().all(|byte| byte.is_ascii_hexdigit()), "port hash for {file}");
    }
}

#[test]
fn every_case_agrees_between_unchanged_upstream_and_retained_port() {
    let evidence = evidence();
    let cases = cases(&evidence);
    assert_eq!(cases.len(), 391);
    for entry in cases {
        assert_eq!(entry["status"], "pass", "{} / {}", entry["group"], entry["name"]);
        // Complete value comparison, not hand-picked fields.
        assert_eq!(
            entry["reference"], entry["candidate"],
            "reference and candidate differ for {} / {}",
            entry["group"], entry["name"]
        );
    }
    let counts = evidence["counts"].as_object().expect("counts are an object");
    let expected = [
        ("config-precedence", 41),
        ("config-parse", 8),
        ("config-env", 9),
        ("config-merge", 4),
        ("config-trust", 12),
        ("config-guards", 22),
        ("config-paths", 4),
        ("config-constants", 1),
        ("store-root", 5),
        ("fast-default", 216),
        ("setting-sources", 27),
        ("env-boolean", 21),
        ("api-key", 11),
        ("provenance", 9),
        ("extension-identity", 1),
    ];
    for (group, count) in expected {
        assert_eq!(counts[group], count, "case count for {group}");
    }
}

#[test]
fn config_precedence_trust_and_safety_caps_are_pinned() {
    let evidence = evidence();

    // CLI is one-shot and never capped by a safer user/project layer.
    let cli = reference(&evidence, "config-precedence", "cli cloud stays uncapped");
    assert_eq!(cli["runtime"]["value"], "cloud");
    assert_eq!(cli["runtime"]["source"], "cli");
    assert_eq!(cli["runtime"]["trustLevel"], "one-shot");
    assert!(cli["runtime"].get("cappedBy").is_none());

    // A trusted project runtime wins over a user runtime; user cloud cannot loosen it.
    let project = reference(&evidence, "config-precedence", "user cloud cannot loosen a safer project local");
    assert_eq!(project["runtime"]["value"], "local");
    assert_eq!(project["runtime"]["source"], "project");
    assert_eq!(project["runtime"]["trustLevel"], "trusted-project");

    // A safer user value caps a riskier project value and reports the capped source.
    let capped = reference(&evidence, "config-precedence", "user local caps a riskier project cloud");
    assert_eq!(capped["runtime"]["value"], "local");
    assert_eq!(capped["runtime"]["source"], "user");
    assert_eq!(capped["runtime"]["cappedBy"]["reason"], "safer-source");
    assert_eq!(capped["runtime"]["cappedBy"]["cappedSource"], "project");
    assert_eq!(capped["runtime"]["cappedBy"]["cappedValue"], "cloud");

    // Cloud fields omit `project` entirely; user never is a plain value, not a cap.
    let handoff = reference(&evidence, "config-precedence", "context handoff project is omitted from cloud precedence (user never)");
    assert_eq!(handoff["cloud"]["contextHandoff"]["value"], "never");
    assert_eq!(handoff["cloud"]["contextHandoff"]["source"], "user");
    assert!(handoff["cloud"]["contextHandoff"].get("cappedBy").is_none());
    let no_loosen = reference(&evidence, "config-precedence", "context handoff project never cannot loosen user bootstrap");
    assert_eq!(no_loosen["cloud"]["contextHandoff"]["value"], "bootstrap");
    assert_eq!(no_loosen["cloud"]["contextHandoff"]["source"], "user");
    assert!(no_loosen["cloud"]["contextHandoff"].get("cappedBy").is_none());

    // envNames are filtered to the safer user allowlist, keeping the original cap.
    let env_names = reference(&evidence, "config-precedence", "cloud envNames session then user cap filters");
    assert_eq!(env_names["cloud"]["envNames"]["value"], serde_json::json!(["A"]));
    assert_eq!(
        env_names["cloud"]["envNames"]["cappedBy"]["cappedValue"],
        serde_json::json!(["A", "B", "C"])
    );
    assert_eq!(
        env_names["cloud"]["envNames"]["cappedBy"]["cappedSource"],
        "session"
    );

    // force participates only in cli/environment/builtin.
    let force = reference(&evidence, "config-precedence", "local force skips project and session");
    assert_eq!(force["local"]["force"]["value"], true);
    assert_eq!(force["local"]["force"]["source"], "environment");
}

#[test]
fn project_config_is_only_loaded_for_trusted_projects() {
    let evidence = evidence();
    assert!(reference(&evidence, "config-trust", "project config untrusted").is_null());
    assert_eq!(
        reference(&evidence, "config-trust", "project config trusted"),
        serde_json::json!({"cloud": {"repo": "r"}, "runtime": "cloud"})
    );
    assert!(reference(&evidence, "config-trust", "project config trusted missing file").is_null());
    assert_eq!(
        reference(&evidence, "config-trust", "load config untrusted"),
        serde_json::json!({"user": {}})
    );
    // Malformed config files are ignored rather than fatal.
    assert_eq!(
        reference(&evidence, "config-trust", "user config invalid JSON"),
        serde_json::json!({})
    );
    assert_eq!(
        reference(&evidence, "config-trust", "user config non-object"),
        serde_json::json!({})
    );
}

#[test]
fn config_writes_are_private_atomic_and_preserve_mode() {
    let evidence = evidence();
    let created = reference(&evidence, "config-trust", "update creates private file");
    // 0o600, pretty JSON with a trailing newline.
    assert_eq!(created["mode"], 0o600);
    assert_eq!(created["content"], "{\n  \"runtime\": \"cloud\"\n}\n");
    assert_eq!(created["updated"], serde_json::json!({"runtime": "cloud"}));

    let preserved = reference(&evidence, "config-trust", "update preserves existing mode");
    // The seeded 0o640 mode survives the atomic replace.
    assert_eq!(preserved["mode"], 0o640);
    assert_eq!(
        preserved["content"],
        "{\n  \"keep\": true,\n  \"local\": {\n    \"resume\": false\n  }\n}\n"
    );
    assert_eq!(
        preserved["updated"],
        serde_json::json!({"keep": true, "local": {"resume": false}})
    );

    // Invalid JSON refuses to update instead of silently overwriting the file.
    let invalid = reference(&evidence, "config-trust", "update rejects invalid JSON");
    let message = invalid["error"].as_str().expect("invalid JSON reports an error");
    assert!(message.starts_with("Invalid JSON in Cursor SDK config <root>/update-invalid/agent/cursor-sdk.json"));
}

#[test]
fn setting_sources_environment_booleans_and_api_keys_are_pinned() {
    let evidence = evidence();
    let resolve = |name: &str| reference(&evidence, "setting-sources", name).clone();

    assert_eq!(resolve("resolve undefined")["resolved"], serde_json::json!(["all"]));
    assert_eq!(resolve("resolve \"\"")["resolved"], serde_json::json!(["all"]));
    assert_eq!(resolve("resolve \"none\"")["resolved"], serde_json::Value::Null);
    assert_eq!(resolve("resolve \"none\"")["serialized"], "none");
    assert_eq!(resolve("resolve \"user,project\"")["resolved"], serde_json::json!(["user", "project"]));
    assert_eq!(resolve("resolve \"user,project\"")["serialized"], "user,project");
    assert_eq!(resolve("resolve \"all,user\"")["resolved"], serde_json::json!(["all", "user"]));
    assert_eq!(resolve("resolve \"all\"")["user"], true);
    assert_eq!(resolve("resolve \"none\"")["user"], false);

    // Environment booleans: explicit pairs, unknown values are absent.
    let boolean = |name: &str| reference(&evidence, "env-boolean", name).clone();
    assert_eq!(boolean("parse \"1\"")["optional"], true);
    assert_eq!(boolean("parse \"yes\"")["optional"], true);
    assert_eq!(boolean("parse \"0\"")["optional"], false);
    assert_eq!(boolean("parse \"disabled\"")["optional"], false);
    assert_eq!(boolean("parse \"maybe\"")["optional"], serde_json::Value::Null);
    assert_eq!(boolean("parse \"maybe\"")["withDefaultTrue"], true);
    assert_eq!(boolean("parse \"maybe\"")["withDefaultFalse"], false);

    // API-key placeholders are never credentials; real values are trimmed.
    let key = |name: &str| reference(&evidence, "api-key", name).clone();
    assert_eq!(key("normalize undefined")["normalize"], serde_json::Value::Null);
    assert_eq!(key("normalize \"CURSOR_API_KEY\"")["normalize"], serde_json::Value::Null);
    assert_eq!(key("normalize \"${CURSOR_API_KEY}\"")["normalize"], serde_json::Value::Null);
    assert_eq!(
        key("normalize \"pi-cursor-sdk-cursor-api-key-placeholder\"")["normalize"],
        serde_json::Value::Null
    );
    assert_eq!(key("normalize \" real-key \"")["normalize"], "real-key");
    // A placeholder resolves through the ambient CURSOR_API_KEY; a real key does not.
    assert_eq!(key("normalize \"CURSOR_API_KEY\"")["resolve"], "env-fixture-key");
    assert_eq!(key("normalize \" real-key \"")["resolve"], "real-key");
}

#[test]
fn request_provenance_identity_is_stable_and_selects_the_occupancy_floor() {
    let evidence = evidence();
    let snapshot = reference(&evidence, "provenance", "capture snapshot");
    assert_eq!(
        snapshot["digest"],
        "cf608870a0608415dff32b9b82023df4953066f673e0efbb958e0ab616e80dc3"
    );
    // Only assistant messages after the last compaction boundary are measured.
    assert_eq!(
        snapshot["measurements"],
        serde_json::json!([
            {"api": "cursor-sdk", "model": "composer-2.5", "provider": "cursor", "tokens": 500},
            {"api": "cursor-sdk", "model": "composer-2.5", "provider": "cursor", "tokens": 700}
        ])
    );
    assert_eq!(snapshot["nativeSourceRoles"], serde_json::json!(["user", "assistant"]));

    let normal = reference(&evidence, "provenance", "resolve normal matching");
    assert_eq!(normal["purpose"], "normal");
    assert_eq!(normal["occupancyFloor"], 700);
    assert_eq!(normal["nativeSourceRoles"], serde_json::json!(["user", "assistant"]));

    // A later measurement outside the model window is skipped for an earlier one.
    let earlier = reference(&evidence, "provenance", "resolve normal picks later within window");
    assert_eq!(earlier["occupancyFloor"], 500);
    assert!(reference(&evidence, "provenance", "resolve normal window excludes all")
        .get("occupancyFloor")
        .is_none());

    // Only a normal request with an equivalent projection carries occupancy.
    for name in ["resolve compaction skips occupancy", "resolve tree skips occupancy", "resolve digest mismatch"] {
        let resolved = reference(&evidence, "provenance", name);
        assert!(resolved.get("occupancyFloor").is_none(), "{name}");
        assert!(resolved.get("nativeSourceRoles").is_none(), "{name}");
    }

    // Sorting message keys makes the digest independent of property insertion order.
    assert_eq!(
        reference(&evidence, "provenance", "digest is property-order stable"),
        "ce9588caeab3a558e215fa28f797b13ffcdd83d21768ee0395ae004425909c5c"
    );
}

#[test]
fn command_flag_and_provider_identity_matches_the_native_host_facade() {
    let evidence = evidence();
    let identity = reference(&evidence, "extension-identity", "commands/flags/handlers/tools/provider");

    let commands = identity["commands"].as_array().expect("commands is an array");
    assert_eq!(commands.len(), 10);
    let names: Vec<&str> = commands
        .iter()
        .map(|command| command["name"].as_str().unwrap())
        .collect();
    assert_eq!(
        names,
        vec![
            "cursor-usage",
            "cursor-runtime",
            "cursor-cloud",
            "cursor-fast",
            "cursor-tools",
            "cursor-http",
            "cursor-local-resume-cleanup",
            "cursor-refresh-config",
            "cursor-mode",
            "cursor-refresh-models",
        ]
    );
    for command in commands {
        assert!(
            !command["description"].as_str().unwrap().is_empty(),
            "description for {}",
            command["name"]
        );
    }

    let flags = identity["flags"].as_array().expect("flags is an array");
    assert_eq!(flags.len(), 21);
    let flag_names: Vec<&str> = flags
        .iter()
        .map(|flag| flag["name"].as_str().unwrap())
        .collect();
    assert_eq!(flag_names[0], "cursor-runtime");
    assert_eq!(flag_names[20], "cursor-mode");
    // Every flag carries a description, a Pi type and a default value.
    for flag in flags {
        assert!(!flag["description"].as_str().unwrap().is_empty(), "flag {}", flag["name"]);
        assert!(matches!(flag["type"].as_str(), Some("string" | "boolean")), "flag type {}", flag["name"]);
        assert!(!flag["default"].is_null(), "flag default {}", flag["name"]);
    }
    assert_eq!(
        case(&evidence, "extension-identity", "commands/flags/handlers/tools/provider")["reference"]
            ["flags"]
            .as_array()
            .unwrap()
            .iter()
            .find(|flag| flag["name"] == "cursor-sandbox")
            .unwrap()["type"],
        "boolean"
    );

    // The provider declaration consumed by `declare`/`register_streaming_provider`.
    let providers = identity["providers"].as_array().expect("providers is an array");
    assert_eq!(providers.len(), 1);
    assert_eq!(providers[0]["id"], "cursor");
    assert_eq!(providers[0]["name"], "Cursor");
    assert_eq!(providers[0]["baseUrl"], "https://cursor.com");
    assert_eq!(providers[0]["authKind"], "api_key");
    assert_eq!(providers[0]["authName"], "Cursor API key");

    // Result hooks the native event registrar maps by tag.
    let handlers: Vec<&str> = identity["handlers"]
        .as_array()
        .unwrap()
        .iter()
        .map(|name| name.as_str().unwrap())
        .collect();
    for required in [
        "project_trust",
        "before_provider_headers",
        "session_start",
        "session_shutdown",
        "session_before_compact",
    ] {
        assert!(handlers.contains(&required), "missing handler {required}");
    }
}
